import React, { useEffect, useMemo, useState } from "react";
import { getBatteries, getBatteryStatus, getTelemetryHistory } from "./api";
import TelemetryChart from "./TelemetryChart";

function Dashboard() {
  const [status, setStatus] = useState({ health: "UNKNOWN", latest: null });
  const [history, setHistory] = useState([]);
  const [batteries, setBatteries] = useState([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState("");

  useEffect(() => {
    let mounted = true;

    const loadData = async () => {
      const batteriesData = await getBatteries(200);
      const batteryItems = (batteriesData.items || []).slice();
      const targetDeviceId = selectedDeviceId || batteryItems[0]?.device_id || "";
      const [statusData, historyData] = await Promise.all([
        getBatteryStatus(targetDeviceId),
        getTelemetryHistory(25, targetDeviceId),
      ]);

      if (!mounted) {
        return;
      }
      setStatus(statusData);
      setHistory((historyData.items || []).slice().reverse());
      setBatteries(batteryItems);
      if (!selectedDeviceId && targetDeviceId) {
        setSelectedDeviceId(targetDeviceId);
      }
    };

    loadData();
    const timer = setInterval(loadData, 5000);

    return () => {
      mounted = false;
      clearInterval(timer);
    };
  }, [selectedDeviceId]);

  const latest = status.latest;

  const chartSeries = useMemo(() => {
    const labels = history.map((item) => {
      const date = new Date(item.timestamp);
      return date.toLocaleTimeString();
    });

    return {
      labels,
      voltage: history.map((item) => item.pack_voltage),
      current: history.map((item) => item.pack_current),
      temperature: history.map((item) => item.temperature),
    };
  }, [history]);

  const healthClass = `health-badge ${status.health.toLowerCase()}`;

  return (
    <main className="layout">
      <header className="topbar">
        <h1>VoltWatch Simulator</h1>
        <div className={healthClass}>{status.health}</div>
      </header>

      <section className="selected-strip">
        <span>Selected Battery:</span>
        <strong>{selectedDeviceId || "None"}</strong>
      </section>

      <section className="cards">
        <article className="card">
          <h2>SOC</h2>
          <div className="soc-value">{latest ? `${latest.soc.toFixed(1)}%` : "--"}</div>
          <div className="gauge">
            <div
              className="gauge-fill"
              style={{ width: `${latest ? Math.max(0, Math.min(100, latest.soc)) : 0}%` }}
            />
          </div>
        </article>

        <article className="card">
          <h2>Pack Voltage</h2>
          <div className="metric">{latest ? `${latest.pack_voltage.toFixed(2)} V` : "--"}</div>
        </article>

        <article className="card">
          <h2>Temperature</h2>
          <div className="metric">{latest ? `${latest.temperature.toFixed(2)} C` : "--"}</div>
        </article>

        <article className="card">
          <h2>Current</h2>
          <div className="metric">{latest ? `${latest.pack_current.toFixed(2)} A` : "--"}</div>
        </article>

        <article className="card">
          <h2>Cycle Count</h2>
          <div className="metric">{latest ? latest.cycle_count : "--"}</div>
        </article>
      </section>

      <section className="charts">
        <TelemetryChart
          title="Voltage vs Time"
          labels={chartSeries.labels}
          values={chartSeries.voltage}
          color="#0f4c5c"
          yLabel="Volts"
        />
        <TelemetryChart
          title="Current vs Time"
          labels={chartSeries.labels}
          values={chartSeries.current}
          color="#e36414"
          yLabel="Amps"
        />
        <TelemetryChart
          title="Temperature vs Time"
          labels={chartSeries.labels}
          values={chartSeries.temperature}
          color="#9a031e"
          yLabel="Celsius"
        />
      </section>

      <section className="table-wrap">
        <h2>Battery List</h2>
        <p className="hint">Click a battery row to load detailed telemetry for that battery.</p>
        <table>
          <thead>
            <tr>
              <th>Entity Name</th>
              <th>packSoC</th>
              <th>Error_Count</th>
              <th>active</th>
              <th>cellIRmax</th>
              <th>lastActivityTime</th>
              <th>packVoltage</th>
              <th>packCurrent</th>
              <th>cycleCount</th>
              <th>health</th>
            </tr>
          </thead>
          <tbody>
            {batteries.map((row) => (
              <tr
                key={row.device_id}
                className={`clickable-row ${row.device_id === selectedDeviceId ? "selected-row" : ""}`}
                onClick={() => setSelectedDeviceId(row.device_id)}
              >
                <td>{row.device_id}</td>
                <td>{row.soc.toFixed(1)}</td>
                <td>{row.alarm_count}</td>
                <td>{row.active ? "true" : "false"}</td>
                <td>{row.cell_imbalance.toFixed(3)}</td>
                <td>{new Date(row.last_activity).toLocaleString()}</td>
                <td>{row.pack_voltage.toFixed(2)} V</td>
                <td>{row.pack_current.toFixed(2)} A</td>
                <td>{row.cycle_count}</td>
                <td>
                  <span className={`mini-health ${row.health.toLowerCase()}`}>{row.health}</span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>

      <section className="table-wrap">
        <h2>Latest Telemetry Records ({selectedDeviceId || "All"})</h2>
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Voltage (V)</th>
              <th>Current (A)</th>
              <th>SOC (%)</th>
              <th>Temp (C)</th>
              <th>Cycle</th>
              <th>Alarms</th>
            </tr>
          </thead>
          <tbody>
            {history.slice(-10).reverse().map((row) => (
              <tr key={row.id}>
                <td>{new Date(row.timestamp).toLocaleTimeString()}</td>
                <td>{row.pack_voltage.toFixed(2)}</td>
                <td>{row.pack_current.toFixed(2)}</td>
                <td>{row.soc.toFixed(1)}</td>
                <td>{row.temperature.toFixed(2)}</td>
                <td>{row.cycle_count}</td>
                <td>{row.alarms.length ? row.alarms.join(", ") : "NONE"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>
    </main>
  );
}

export default Dashboard;
